-- SGUEES#191: Área > ciclo > sedes > facultades > carreras. Importación conservadora en borrador.
USE SGUEES;
GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID('dbo.ACA_CICLOS_ACADEMICOS') IS NULL
CREATE TABLE dbo.ACA_CICLOS_ACADEMICOS(
 CORR_CICLO_ACADEMICO int IDENTITY PRIMARY KEY,CORR_EMPRESA int NOT NULL REFERENCES dbo.GEN_EMPRESA(CORR_EMPRESA),
 CORR_AREA_ACADEMICA int NOT NULL REFERENCES dbo.ACA_AREAS_ACADEMICAS(CORR_AREA_ACADEMICA),ANIO smallint NOT NULL,NUMERO_PERIODO tinyint NOT NULL,
 FECHA_INICIO date NOT NULL,FECHA_FIN date NOT NULL,FECHA_INICIO_INSCRIPCION date NOT NULL,FECHA_FIN_INSCRIPCION date NOT NULL,
 ESTADO varchar(12) NOT NULL DEFAULT 'BORRADOR' CHECK(ESTADO IN ('BORRADOR','HABILITADO','CERRADO')),
 REQUIERE_REVISION bit NOT NULL DEFAULT 0,USUARIO_CREA varchar(50) NOT NULL,ESTACION_CREA varchar(100) NOT NULL,FECHA_CREA datetime NOT NULL DEFAULT GETDATE(),
 USUARIO_ACTU varchar(50) NULL,ESTACION_ACTU varchar(100) NULL,FECHA_ACTU datetime NULL,
 CONSTRAINT UQ_ACA_CICLO_AREA UNIQUE(CORR_EMPRESA,CORR_AREA_ACADEMICA,ANIO,NUMERO_PERIODO));
IF OBJECT_ID('dbo.ACA_CICLOS_SEDES') IS NULL
CREATE TABLE dbo.ACA_CICLOS_SEDES(CORR_CICLO_ACADEMICO int NOT NULL REFERENCES dbo.ACA_CICLOS_ACADEMICOS(CORR_CICLO_ACADEMICO),
 CORR_SEDE int NOT NULL REFERENCES dbo.GEN_SEDES(CORR_SEDE),ACTIVO bit NOT NULL,PRIMARY KEY(CORR_CICLO_ACADEMICO,CORR_SEDE));
IF OBJECT_ID('dbo.ACA_CICLOS_FACULTADES_SEDES') IS NULL
CREATE TABLE dbo.ACA_CICLOS_FACULTADES_SEDES(CORR_CICLO_ACADEMICO int NOT NULL,CORR_SEDE int NOT NULL,CORR_FACULTAD int NOT NULL,ACTIVO bit NOT NULL,
 PRIMARY KEY(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_FACULTAD),
 FOREIGN KEY(CORR_CICLO_ACADEMICO,CORR_SEDE) REFERENCES dbo.ACA_CICLOS_SEDES(CORR_CICLO_ACADEMICO,CORR_SEDE),
 FOREIGN KEY(CORR_FACULTAD,CORR_SEDE) REFERENCES dbo.ACA_FACULTADES_SEDES(CORR_FACULTAD,CORR_SEDE));
IF OBJECT_ID('dbo.ACA_CICLOS_CARRERAS_SEDES') IS NULL
CREATE TABLE dbo.ACA_CICLOS_CARRERAS_SEDES(CORR_CICLO_ACADEMICO int NOT NULL,CORR_SEDE int NOT NULL,CORR_FACULTAD int NOT NULL,CORR_CARRERA int NOT NULL,
 ACTIVO bit NOT NULL,CORR_PERIODO_ACADEMICO int NULL REFERENCES dbo.ACA_PERIODOS_ACADEMICOS(CORR_PERIODO_ACADEMICO),
 PRIMARY KEY(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_CARRERA),
 FOREIGN KEY(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_FACULTAD) REFERENCES dbo.ACA_CICLOS_FACULTADES_SEDES(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_FACULTAD),
 FOREIGN KEY(CORR_CARRERA,CORR_SEDE) REFERENCES dbo.ACA_CARRERAS_SEDES(CORR_CARRERA,CORR_SEDE));
IF OBJECT_ID('dbo.ACA_CICLOS_BITACORA') IS NULL
CREATE TABLE dbo.ACA_CICLOS_BITACORA(ID_BITACORA bigint IDENTITY PRIMARY KEY,CORR_CICLO_ACADEMICO int NOT NULL REFERENCES dbo.ACA_CICLOS_ACADEMICOS(CORR_CICLO_ACADEMICO),
 OPERACION varchar(20) NOT NULL,USUARIO varchar(50) NOT NULL,ESTACION varchar(100) NOT NULL,FECHA datetime2 NOT NULL DEFAULT SYSDATETIME(),DATOS nvarchar(max) NOT NULL);
IF COL_LENGTH('dbo.ACA_PERIODOS_ACADEMICOS','CORR_CICLO_ACADEMICO') IS NULL
 ALTER TABLE dbo.ACA_PERIODOS_ACADEMICOS ADD CORR_CICLO_ACADEMICO int NULL REFERENCES dbo.ACA_CICLOS_ACADEMICOS(CORR_CICLO_ACADEMICO),ES_GESTIONADO_CICLO bit NOT NULL CONSTRAINT DF_PER_GEST_CICLO DEFAULT 0;
GO
CREATE OR ALTER VIEW dbo.V_ACA_CICLOS AS
SELECT C.*,A.NOMBRE_AREA,
 COALESCE(STUFF((SELECT NCHAR(10)+LTRIM(RTRIM(G.NOMBRE_SEDE)) FROM dbo.ACA_CICLOS_SEDES S
  JOIN dbo.GEN_SEDES G ON G.CORR_SEDE=S.CORR_SEDE AND G.CORR_EMPRESA=C.CORR_EMPRESA
  WHERE S.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO AND S.ACTIVO=1 ORDER BY G.NOMBRE_SEDE,S.CORR_SEDE
  FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N''),N'Sin sedes seleccionadas') AS NOMBRES_SEDES,
 COALESCE(STUFF((SELECT NCHAR(10)+LTRIM(RTRIM(G.NOMBRE_SEDE))+N': '+LTRIM(RTRIM(F.NOMBRE_FACULTAD))
  FROM dbo.ACA_CICLOS_FACULTADES_SEDES CF JOIN dbo.ACA_CICLOS_SEDES S ON S.CORR_CICLO_ACADEMICO=CF.CORR_CICLO_ACADEMICO AND S.CORR_SEDE=CF.CORR_SEDE
  JOIN dbo.GEN_SEDES G ON G.CORR_SEDE=S.CORR_SEDE AND G.CORR_EMPRESA=C.CORR_EMPRESA
  JOIN dbo.ACA_FACULTADES F ON F.CORR_FACULTAD=CF.CORR_FACULTAD AND F.CORR_EMPRESA=C.CORR_EMPRESA
  WHERE CF.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO AND CF.ACTIVO=1 AND S.ACTIVO=1
  ORDER BY G.NOMBRE_SEDE,F.NOMBRE_FACULTAD,CF.CORR_FACULTAD FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,1,N''),N'Sin facultades seleccionadas') AS NOMBRES_FACULTADES_SEDES,
 (SELECT COUNT(*) FROM dbo.ACA_CICLOS_SEDES S WHERE S.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO AND S.ACTIVO=1) AS SEDES,
 (SELECT COUNT(*) FROM dbo.ACA_CICLOS_FACULTADES_SEDES F JOIN dbo.ACA_CICLOS_SEDES S ON S.CORR_CICLO_ACADEMICO=F.CORR_CICLO_ACADEMICO AND S.CORR_SEDE=F.CORR_SEDE
  WHERE F.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO AND F.ACTIVO=1 AND S.ACTIVO=1) AS FACULTADES_SEDES,
 (SELECT COUNT(*) FROM dbo.ACA_CICLOS_CARRERAS_SEDES R JOIN dbo.ACA_CICLOS_FACULTADES_SEDES F ON F.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO AND F.CORR_SEDE=R.CORR_SEDE AND F.CORR_FACULTAD=R.CORR_FACULTAD
  JOIN dbo.ACA_CICLOS_SEDES S ON S.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO AND S.CORR_SEDE=R.CORR_SEDE
  WHERE R.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO AND R.ACTIVO=1 AND F.ACTIVO=1 AND S.ACTIVO=1) AS CARRERAS_SEDES
FROM dbo.ACA_CICLOS_ACADEMICOS C JOIN dbo.ACA_AREAS_ACADEMICAS A ON A.CORR_AREA_ACADEMICA=C.CORR_AREA_ACADEMICA AND A.CORR_EMPRESA=C.CORR_EMPRESA;
GO
CREATE OR ALTER VIEW dbo.V_ACA_CICLOS_RESUMEN AS
SELECT R.*,H.CORR_EMPRESA,H.CORR_AREA_ACADEMICA,S.NOMBRE_SEDE,F.NOMBRE_FACULTAD,C.NOMBRE_CARRERA,
 CAST(CASE WHEN R.ACTIVO=1 AND CF.ACTIVO=1 AND CS.ACTIVO=1 THEN 1 ELSE 0 END AS bit) AS SELECCIONADA,
 CASE WHEN C.CORR_EMPRESA<>H.CORR_EMPRESA OR S.CORR_EMPRESA<>H.CORR_EMPRESA OR F.CORR_EMPRESA<>H.CORR_EMPRESA OR A.CORR_EMPRESA<>H.CORR_EMPRESA THEN N'Empresa incompatible'
 WHEN C.CORR_AREA_ACADEMICA<>H.CORR_AREA_ACADEMICA OR C.CORR_FACULTAD<>R.CORR_FACULTAD THEN N'Área o facultad de la carrera incompatible'
 WHEN ISNULL(S.ESTADO_SEDE,'')<>'A' OR A.ACTIVO=0 OR F.ACTIVO=0 OR C.ACTIVO=0 THEN N'Sede, área, facultad o carrera inactiva'
 WHEN ISNULL(FS.ACTIVO,0)=0 OR ISNULL(RS.ACTIVO,0)=0 THEN N'Asociación institucional por sede inactiva'
 WHEN C.CORR_GRADO_ACADEMICO IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.ACA_GRADOS_ACADEMICOS G WHERE G.CORR_GRADO_ACADEMICO=C.CORR_GRADO_ACADEMICO AND G.CORR_EMPRESA=H.CORR_EMPRESA AND G.ACTIVO=1) THEN N'Grado académico inactivo'
 WHEN NOT EXISTS(SELECT 1 FROM dbo.ACA_PLANES_ACADEMICOS P JOIN dbo.ACA_MODALIDADES_ACADEMICAS M ON M.CORR_MODALIDAD=P.CORR_MODALIDAD AND M.CORR_EMPRESA=H.CORR_EMPRESA AND M.ACTIVO=1
  WHERE P.CORR_CARRERA=R.CORR_CARRERA AND P.PLAN_VIGENTE=1 AND P.FECHA_VIGENCIA_INICIO<=H.FECHA_INICIO AND (P.FECHA_VIGENCIA_FIN IS NULL OR P.FECHA_VIGENCIA_FIN>=H.FECHA_INICIO)) THEN N'Sin plan y modalidad elegibles al inicio académico'
 ELSE N'Lista para apertura' END AS DIAGNOSTICO
FROM dbo.ACA_CICLOS_CARRERAS_SEDES R
JOIN dbo.ACA_CICLOS_ACADEMICOS H ON H.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO
JOIN dbo.ACA_CICLOS_SEDES CS ON CS.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO AND CS.CORR_SEDE=R.CORR_SEDE
JOIN dbo.ACA_CICLOS_FACULTADES_SEDES CF ON CF.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO AND CF.CORR_SEDE=R.CORR_SEDE AND CF.CORR_FACULTAD=R.CORR_FACULTAD
JOIN dbo.GEN_SEDES S ON S.CORR_SEDE=R.CORR_SEDE JOIN dbo.ACA_CARRERAS C ON C.CORR_CARRERA=R.CORR_CARRERA
JOIN dbo.ACA_FACULTADES F ON F.CORR_FACULTAD=R.CORR_FACULTAD JOIN dbo.ACA_AREAS_ACADEMICAS A ON A.CORR_AREA_ACADEMICA=H.CORR_AREA_ACADEMICA
LEFT JOIN dbo.ACA_FACULTADES_SEDES FS ON FS.CORR_SEDE=R.CORR_SEDE AND FS.CORR_FACULTAD=R.CORR_FACULTAD
LEFT JOIN dbo.ACA_CARRERAS_SEDES RS ON RS.CORR_SEDE=R.CORR_SEDE AND RS.CORR_CARRERA=R.CORR_CARRERA;
GO
CREATE OR ALTER FUNCTION dbo.FN_ACA_OFERTA_CICLO_V3(@CORR_EMPRESA int,@CORR_SEDE int,@CORR_AREA_ACADEMICA int,@ANIO smallint,@NUMERO_PERIODO tinyint,@FECHA_REFERENCIA date)
RETURNS TABLE AS RETURN
WITH E AS(
 SELECT R.CORR_CICLO_ACADEMICO,R.CORR_SEDE,R.CORR_CARRERA,C.CODIGO_CARRERA,R.NOMBRE_CARRERA,R.CORR_PERIODO_ACADEMICO,
  P.CORR_PLAN_ACADEMICO,P.CODIGO_PLAN,P.ANIO_PLAN,M.CORR_MODALIDAD,M.NOMBRE_MODALIDAD,H.FECHA_INICIO,H.FECHA_FIN,H.FECHA_INICIO_INSCRIPCION,H.FECHA_FIN_INSCRIPCION,
  ROW_NUMBER() OVER(PARTITION BY R.CORR_CARRERA,M.CORR_MODALIDAD ORDER BY P.ANIO_PLAN DESC,P.FECHA_VIGENCIA_INICIO DESC,P.CORR_PLAN_ACADEMICO DESC) AS RN
 FROM dbo.V_ACA_CICLOS_RESUMEN R JOIN dbo.ACA_CICLOS_ACADEMICOS H ON H.CORR_CICLO_ACADEMICO=R.CORR_CICLO_ACADEMICO
 JOIN dbo.ACA_CARRERAS C ON C.CORR_CARRERA=R.CORR_CARRERA
 JOIN dbo.ACA_PLANES_ACADEMICOS P ON P.CORR_CARRERA=R.CORR_CARRERA AND P.PLAN_VIGENTE=1 AND P.FECHA_VIGENCIA_INICIO<=H.FECHA_INICIO AND (P.FECHA_VIGENCIA_FIN IS NULL OR P.FECHA_VIGENCIA_FIN>=H.FECHA_INICIO)
 JOIN dbo.ACA_MODALIDADES_ACADEMICAS M ON M.CORR_MODALIDAD=P.CORR_MODALIDAD AND M.CORR_EMPRESA=H.CORR_EMPRESA AND M.ACTIVO=1
 JOIN dbo.ACA_PERIODOS_ACADEMICOS PA ON PA.CORR_PERIODO_ACADEMICO=R.CORR_PERIODO_ACADEMICO AND PA.ACTIVO=1 AND PA.CORR_CICLO_ACADEMICO=H.CORR_CICLO_ACADEMICO
  AND PA.CORR_SEDE=R.CORR_SEDE AND PA.CORR_CARRERA=R.CORR_CARRERA AND PA.CORR_AREA_ACADEMICA=H.CORR_AREA_ACADEMICA AND PA.ANIO=H.ANIO AND PA.NUMERO_PERIODO=H.NUMERO_PERIODO
 WHERE H.CORR_EMPRESA=@CORR_EMPRESA AND H.CORR_AREA_ACADEMICA=@CORR_AREA_ACADEMICA AND R.CORR_SEDE=@CORR_SEDE
  AND H.ANIO=@ANIO AND H.NUMERO_PERIODO=@NUMERO_PERIODO AND H.ESTADO='HABILITADO' AND H.REQUIERE_REVISION=0
  AND R.SELECCIONADA=1 AND R.DIAGNOSTICO=N'Lista para apertura' AND @FECHA_REFERENCIA BETWEEN H.FECHA_INICIO_INSCRIPCION AND H.FECHA_FIN_INSCRIPCION
)
SELECT * FROM E WHERE RN=1;
GO
CREATE OR ALTER PROCEDURE dbo.PR_ACA_CICLO_AUDITAR @id int,@operacion varchar(20),@usuario varchar(50),@estacion varchar(100) AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @datos nvarchar(max)=(SELECT H.*,
  JSON_QUERY((SELECT * FROM dbo.ACA_CICLOS_SEDES WHERE CORR_CICLO_ACADEMICO=@id FOR JSON PATH)) AS SEDES,
  JSON_QUERY((SELECT * FROM dbo.ACA_CICLOS_FACULTADES_SEDES WHERE CORR_CICLO_ACADEMICO=@id FOR JSON PATH)) AS FACULTADES,
  JSON_QUERY((SELECT * FROM dbo.ACA_CICLOS_CARRERAS_SEDES WHERE CORR_CICLO_ACADEMICO=@id FOR JSON PATH)) AS CARRERAS
  FROM dbo.ACA_CICLOS_ACADEMICOS H WHERE H.CORR_CICLO_ACADEMICO=@id FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 INSERT dbo.ACA_CICLOS_BITACORA(CORR_CICLO_ACADEMICO,OPERACION,USUARIO,ESTACION,DATOS) VALUES(@id,@operacion,@usuario,@estacion,@datos);
END;
GO
CREATE OR ALTER PROCEDURE dbo.PRAL_MTTO_ACA_CICLOS
 @OPERACION varchar(20),@CORR_EMPRESA int,@CORR_CICLO_ACADEMICO int OUTPUT,@CORR_AREA_ACADEMICA int=NULL,@ANIO int=NULL,@NUMERO_PERIODO int=NULL,
 @FECHA_INICIO date=NULL,@FECHA_FIN date=NULL,@FECHA_INICIO_INSCRIPCION date=NULL,@FECHA_FIN_INSCRIPCION date=NULL,
 @CORR_SEDE int=NULL,@CORR_FACULTAD int=NULL,@CORR_CARRERA int=NULL,@ACTIVO bit=1,@SYS_LOGIN_USUARIO varchar(50),@SYS_ESTACION varchar(100),
 @SYS_NUMERO_ERROR int OUTPUT,@SYS_MENSAJE_ERROR nvarchar(4000) OUTPUT
AS BEGIN
 SET NOCOUNT ON;SET XACT_ABORT ON;
 DECLARE @T int=@@TRANCOUNT,@estado varchar(12),@area int,@revision bit,@y smallint,@n tinyint,@i date,@fin date,@ii date,@fi date,@empresa int;
 SELECT @SYS_NUMERO_ERROR=0,@SYS_MENSAJE_ERROR=N'';
 BEGIN TRY
  IF NULLIF(LTRIM(RTRIM(@SYS_LOGIN_USUARIO)),'') IS NULL THROW 51000,N'No se encontró el usuario de sesión.',1;
  IF @OPERACION NOT IN ('CREAR','GUARDAR','SEDE','FACULTAD','CARRERA','TODAS','HABILITAR','BORRADOR','CERRAR') OR @OPERACION IS NULL THROW 51000,N'Operación no válida.',1;
  IF @T=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CICLOS_MTTO;
  SELECT @empresa=CORR_EMPRESA FROM dbo.GEN_EMPRESA WITH(UPDLOCK,HOLDLOCK) WHERE CORR_EMPRESA=@CORR_EMPRESA;
  IF @empresa IS NULL THROW 51000,N'La empresa de sesión no existe.',1;
  IF @OPERACION='CREAR'
  BEGIN
   SET @estado='BORRADOR';
   IF NOT EXISTS(SELECT 1 FROM dbo.ACA_AREAS_ACADEMICAS WITH(HOLDLOCK) WHERE CORR_AREA_ACADEMICA=@CORR_AREA_ACADEMICA AND CORR_EMPRESA=@CORR_EMPRESA AND ACTIVO=1) THROW 51000,N'Seleccione un área activa de su empresa.',1;
  END
  ELSE
  BEGIN
   SELECT @estado=ESTADO,@area=CORR_AREA_ACADEMICA,@revision=REQUIERE_REVISION,@y=ANIO,@n=NUMERO_PERIODO,@i=FECHA_INICIO,@fin=FECHA_FIN,@ii=FECHA_INICIO_INSCRIPCION,@fi=FECHA_FIN_INSCRIPCION
   FROM dbo.ACA_CICLOS_ACADEMICOS WITH(UPDLOCK,HOLDLOCK) WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_EMPRESA=@CORR_EMPRESA;
   IF @estado IS NULL THROW 51000,N'El ciclo no existe en su empresa.',1;
   IF @OPERACION NOT IN ('HABILITAR','BORRADOR','CERRAR') AND @estado<>'BORRADOR' THROW 51000,N'Pase el ciclo a borrador antes de modificar calendario u oferta.',1;
  END;
  IF @OPERACION IN ('CREAR','GUARDAR')
  BEGIN
   IF @ANIO IS NULL OR @ANIO NOT BETWEEN 1 AND 9999 OR @NUMERO_PERIODO IS NULL OR @NUMERO_PERIODO NOT BETWEEN 1 AND 255 THROW 51000,N'Ingrese año entre 1 y 9999 y número entre 1 y 255.',1;
   IF @FECHA_INICIO IS NULL OR @FECHA_FIN IS NULL OR @FECHA_INICIO_INSCRIPCION IS NULL OR @FECHA_FIN_INSCRIPCION IS NULL THROW 51000,N'Complete las cuatro fechas del calendario común.',1;
   IF @FECHA_FIN<@FECHA_INICIO OR @FECHA_FIN_INSCRIPCION<@FECHA_INICIO_INSCRIPCION OR @FECHA_FIN_INSCRIPCION>@FECHA_FIN THROW 51000,N'Revise el orden de fechas y que la inscripción cierre antes del fin académico.',1;
   IF @OPERACION='GUARDAR' AND (@CORR_AREA_ACADEMICA<>@area OR @ANIO<>@y OR @NUMERO_PERIODO<>@n OR @CORR_AREA_ACADEMICA IS NULL) THROW 51000,N'El área, año y número identifican el ciclo y no se pueden cambiar; cree otro ciclo.',1;
   IF @OPERACION='CREAR'
   BEGIN
    INSERT dbo.ACA_CICLOS_ACADEMICOS(CORR_EMPRESA,CORR_AREA_ACADEMICA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,USUARIO_CREA,ESTACION_CREA)
    VALUES(@CORR_EMPRESA,@CORR_AREA_ACADEMICA,@ANIO,@NUMERO_PERIODO,@FECHA_INICIO,@FECHA_FIN,@FECHA_INICIO_INSCRIPCION,@FECHA_FIN_INSCRIPCION,@SYS_LOGIN_USUARIO,@SYS_ESTACION);
    SET @CORR_CICLO_ACADEMICO=CONVERT(int,SCOPE_IDENTITY());
   END
   ELSE UPDATE dbo.ACA_CICLOS_ACADEMICOS SET FECHA_INICIO=@FECHA_INICIO,FECHA_FIN=@FECHA_FIN,FECHA_INICIO_INSCRIPCION=@FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION=@FECHA_FIN_INSCRIPCION,
    REQUIERE_REVISION=0 WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO;
  END;
  IF @OPERACION IN ('SEDE','FACULTAD','CARRERA','TODAS')
  BEGIN
   IF @ACTIVO IS NULL THROW 51000,N'Indique si desea seleccionar o retirar la asignación.',1;
   IF NOT EXISTS(SELECT 1 FROM dbo.GEN_SEDES WITH(HOLDLOCK) WHERE CORR_SEDE=@CORR_SEDE AND CORR_EMPRESA=@CORR_EMPRESA AND (@ACTIVO=0 OR ESTADO_SEDE='A')) THROW 51000,N'Seleccione una sede activa de su empresa.',1;
   IF @OPERACION='SEDE'
   BEGIN
    IF EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE)
     UPDATE dbo.ACA_CICLOS_SEDES SET ACTIVO=@ACTIVO WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE;
    ELSE INSERT dbo.ACA_CICLOS_SEDES VALUES(@CORR_CICLO_ACADEMICO,@CORR_SEDE,@ACTIVO);
   END
   ELSE
   BEGIN
    IF NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND ACTIVO=1) THROW 51000,N'Habilite primero esta sede dentro del ciclo.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.ACA_FACULTADES F WITH(HOLDLOCK) JOIN dbo.ACA_FACULTADES_SEDES FS WITH(HOLDLOCK) ON FS.CORR_FACULTAD=F.CORR_FACULTAD AND FS.CORR_SEDE=@CORR_SEDE
     WHERE F.CORR_FACULTAD=@CORR_FACULTAD AND F.CORR_EMPRESA=@CORR_EMPRESA AND (@ACTIVO=0 OR (F.ACTIVO=1 AND FS.ACTIVO=1))) THROW 51000,N'La facultad no tiene autorización activa en esa sede.',1;
    IF @OPERACION='FACULTAD'
    BEGIN
     IF @ACTIVO=1 AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CARRERAS WHERE CORR_EMPRESA=@CORR_EMPRESA AND CORR_AREA_ACADEMICA=@area AND CORR_FACULTAD=@CORR_FACULTAD AND ACTIVO=1) THROW 51000,N'La facultad no tiene carreras activas del área seleccionada.',1;
     IF EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_FACULTADES_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_FACULTAD=@CORR_FACULTAD)
      UPDATE dbo.ACA_CICLOS_FACULTADES_SEDES SET ACTIVO=@ACTIVO WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_FACULTAD=@CORR_FACULTAD;
     ELSE INSERT dbo.ACA_CICLOS_FACULTADES_SEDES VALUES(@CORR_CICLO_ACADEMICO,@CORR_SEDE,@CORR_FACULTAD,@ACTIVO);
    END
    ELSE
    BEGIN
     IF NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_FACULTADES_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_FACULTAD=@CORR_FACULTAD AND ACTIVO=1) THROW 51000,N'Seleccione primero la facultad dentro de la sede del ciclo.',1;
     IF @OPERACION='TODAS'
     BEGIN
      INSERT dbo.ACA_CICLOS_CARRERAS_SEDES(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_FACULTAD,CORR_CARRERA,ACTIVO)
      SELECT @CORR_CICLO_ACADEMICO,@CORR_SEDE,@CORR_FACULTAD,C.CORR_CARRERA,1 FROM dbo.ACA_CARRERAS C WITH(HOLDLOCK)
      JOIN dbo.ACA_CARRERAS_SEDES CS WITH(HOLDLOCK) ON CS.CORR_CARRERA=C.CORR_CARRERA AND CS.CORR_SEDE=@CORR_SEDE AND CS.ACTIVO=1
      WHERE C.CORR_EMPRESA=@CORR_EMPRESA AND C.CORR_AREA_ACADEMICA=@area AND C.CORR_FACULTAD=@CORR_FACULTAD AND C.ACTIVO=1
       AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES R WHERE R.CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND R.CORR_SEDE=@CORR_SEDE AND R.CORR_CARRERA=C.CORR_CARRERA);
      UPDATE R SET ACTIVO=1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES R JOIN dbo.ACA_CARRERAS C ON C.CORR_CARRERA=R.CORR_CARRERA
       JOIN dbo.ACA_CARRERAS_SEDES CS ON CS.CORR_CARRERA=C.CORR_CARRERA AND CS.CORR_SEDE=R.CORR_SEDE AND CS.ACTIVO=1
       WHERE R.CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND R.CORR_SEDE=@CORR_SEDE AND R.CORR_FACULTAD=@CORR_FACULTAD AND C.CORR_EMPRESA=@CORR_EMPRESA AND C.CORR_AREA_ACADEMICA=@area AND C.CORR_FACULTAD=@CORR_FACULTAD AND C.ACTIVO=1;
     END
     ELSE
     BEGIN
      IF NOT (@ACTIVO=0 AND EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_FACULTAD=@CORR_FACULTAD AND CORR_CARRERA=@CORR_CARRERA))
       AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CARRERAS C WITH(HOLDLOCK) JOIN dbo.ACA_CARRERAS_SEDES CS WITH(HOLDLOCK) ON CS.CORR_CARRERA=C.CORR_CARRERA AND CS.CORR_SEDE=@CORR_SEDE
       WHERE C.CORR_CARRERA=@CORR_CARRERA AND C.CORR_EMPRESA=@CORR_EMPRESA AND C.CORR_AREA_ACADEMICA=@area AND C.CORR_FACULTAD=@CORR_FACULTAD AND (@ACTIVO=0 OR (C.ACTIVO=1 AND CS.ACTIVO=1))) THROW 51000,N'La carrera no coincide con el área, facultad y autorización por sede.',1;
      IF EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_CARRERA=@CORR_CARRERA)
       UPDATE dbo.ACA_CICLOS_CARRERAS_SEDES SET ACTIVO=@ACTIVO WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@CORR_SEDE AND CORR_CARRERA=@CORR_CARRERA;
      ELSE INSERT dbo.ACA_CICLOS_CARRERAS_SEDES(CORR_CICLO_ACADEMICO,CORR_SEDE,CORR_FACULTAD,CORR_CARRERA,ACTIVO) VALUES(@CORR_CICLO_ACADEMICO,@CORR_SEDE,@CORR_FACULTAD,@CORR_CARRERA,@ACTIVO);
     END;
    END;
   END;
  END;
  IF @OPERACION='HABILITAR'
  BEGIN
   IF @revision=1 THROW 51000,N'Revise y guarde primero el calendario común importado.',1;
   IF NOT EXISTS(SELECT 1 FROM dbo.ACA_AREAS_ACADEMICAS WITH(HOLDLOCK) WHERE CORR_AREA_ACADEMICA=@area AND CORR_EMPRESA=@CORR_EMPRESA AND ACTIVO=1) THROW 51000,N'El área debe estar activa.',1;
   IF @fin<@i OR @fi<@ii OR @fi>@fin THROW 51000,N'El calendario común no es válido.',1;
   IF NOT EXISTS(SELECT 1 FROM dbo.V_ACA_CICLOS_RESUMEN WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND SELECCIONADA=1) THROW 51000,N'Seleccione al menos una carrera para apertura.',1;
   IF EXISTS(SELECT 1 FROM dbo.V_ACA_CICLOS_RESUMEN WITH(HOLDLOCK) WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND SELECCIONADA=1 AND DIAGNOSTICO<>N'Lista para apertura') THROW 51000,N'Hay carreras seleccionadas con observaciones. Revise Resumen antes de habilitar.',1;
   IF EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_SEDES S WHERE S.CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND S.ACTIVO=1 AND NOT EXISTS(SELECT 1 FROM dbo.V_ACA_CICLOS_RESUMEN R WHERE R.CORR_CICLO_ACADEMICO=S.CORR_CICLO_ACADEMICO AND R.CORR_SEDE=S.CORR_SEDE AND R.SELECCIONADA=1)) THROW 51000,N'Cada sede habilitada debe tener carreras seleccionadas.',1;
   IF EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_FACULTADES_SEDES F JOIN dbo.ACA_CICLOS_SEDES S ON S.CORR_CICLO_ACADEMICO=F.CORR_CICLO_ACADEMICO AND S.CORR_SEDE=F.CORR_SEDE AND S.ACTIVO=1
    WHERE F.CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND F.ACTIVO=1 AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES R WHERE R.CORR_CICLO_ACADEMICO=F.CORR_CICLO_ACADEMICO AND R.CORR_SEDE=F.CORR_SEDE AND R.CORR_FACULTAD=F.CORR_FACULTAD AND R.ACTIVO=1)) THROW 51000,N'Cada facultad habilitada debe tener carreras seleccionadas.',1;
   -- Crear o reutilizar los períodos específicos; mantiene sus PK históricas y registra sus calendarios.
   DECLARE @s int,@f int,@ca int,@p int;
   DECLARE CUR_CARRERAS CURSOR LOCAL FAST_FORWARD FOR SELECT CORR_SEDE,CORR_FACULTAD,CORR_CARRERA FROM dbo.V_ACA_CICLOS_RESUMEN WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND SELECCIONADA=1;
   OPEN CUR_CARRERAS;FETCH NEXT FROM CUR_CARRERAS INTO @s,@f,@ca;
   WHILE @@FETCH_STATUS=0
   BEGIN
    SET @p=NULL;
    IF (SELECT COUNT(*) FROM dbo.ACA_PERIODOS_ACADEMICOS WITH(UPDLOCK,HOLDLOCK) WHERE CORR_SEDE=@s AND CORR_AREA_ACADEMICA=@area AND ANIO=@y AND NUMERO_PERIODO=@n AND CORR_CARRERA=@ca AND (CORR_FACULTAD=@f OR CORR_FACULTAD IS NULL))>1 THROW 51000,N'Hay varios períodos específicos para una carrera y sede. Revise sus referencias antes de habilitar.',1;
    SELECT @p=CORR_PERIODO_ACADEMICO FROM dbo.ACA_PERIODOS_ACADEMICOS WITH(UPDLOCK,HOLDLOCK) WHERE CORR_SEDE=@s AND CORR_AREA_ACADEMICA=@area AND ANIO=@y AND NUMERO_PERIODO=@n AND CORR_CARRERA=@ca AND (CORR_FACULTAD=@f OR CORR_FACULTAD IS NULL);
    IF @p IS NULL
    BEGIN
     INSERT dbo.ACA_PERIODOS_ACADEMICOS(CORR_SEDE,CORR_AREA_ACADEMICA,CORR_FACULTAD,CORR_CARRERA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,ACTIVO,USUARIO_CREA,ESTACION_CREA,FECHA_CREA,CORR_CICLO_ACADEMICO,ES_GESTIONADO_CICLO)
     VALUES(@s,@area,@f,@ca,@y,@n,@i,@fin,@ii,@fi,1,@SYS_LOGIN_USUARIO,@SYS_ESTACION,GETDATE(),@CORR_CICLO_ACADEMICO,1);SET @p=CONVERT(int,SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
     IF NOT EXISTS(SELECT 1 FROM dbo.ACA_PERIODOS_ACADEMICOS_BITACORA WHERE CORR_PERIODO_ACADEMICO=@p)
      INSERT dbo.ACA_PERIODOS_ACADEMICOS_BITACORA(CORR_PERIODO_ACADEMICO,CORR_SEDE,CORR_AREA_ACADEMICA,CORR_FACULTAD,CORR_CARRERA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,ACTIVO,USUARIO_CREA,ESTACION_CREA,FECHA_CREA,USUARIO_ACTU,ESTACION_ACTU,FECHA_ACTU,TIPO_CAMBIO,USUARIO_CAMBIO)
      SELECT CORR_PERIODO_ACADEMICO,CORR_SEDE,CORR_AREA_ACADEMICA,CORR_FACULTAD,CORR_CARRERA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,ACTIVO,USUARIO_CREA,ESTACION_CREA,FECHA_CREA,USUARIO_ACTU,ESTACION_ACTU,FECHA_ACTU,'BASE',@SYS_LOGIN_USUARIO FROM dbo.ACA_PERIODOS_ACADEMICOS WHERE CORR_PERIODO_ACADEMICO=@p;
     UPDATE dbo.ACA_PERIODOS_ACADEMICOS SET FECHA_INICIO=@i,FECHA_FIN=@fin,FECHA_INICIO_INSCRIPCION=@ii,FECHA_FIN_INSCRIPCION=@fi,ACTIVO=1,CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO,ES_GESTIONADO_CICLO=1,USUARIO_ACTU=@SYS_LOGIN_USUARIO,ESTACION_ACTU=@SYS_ESTACION,FECHA_ACTU=GETDATE() WHERE CORR_PERIODO_ACADEMICO=@p;
    END;
    UPDATE dbo.ACA_CICLOS_CARRERAS_SEDES SET CORR_PERIODO_ACADEMICO=@p WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND CORR_SEDE=@s AND CORR_CARRERA=@ca;
    FETCH NEXT FROM CUR_CARRERAS INTO @s,@f,@ca;
   END;CLOSE CUR_CARRERAS;DEALLOCATE CUR_CARRERAS;
   UPDATE dbo.ACA_CICLOS_ACADEMICOS SET ESTADO='HABILITADO' WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO;
  END;
  IF @OPERACION IN ('BORRADOR','CERRAR') UPDATE dbo.ACA_CICLOS_ACADEMICOS SET ESTADO=CASE WHEN @OPERACION='BORRADOR' THEN 'BORRADOR' ELSE 'CERRADO' END WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO;
  IF @OPERACION IN ('HABILITAR','BORRADOR','CERRAR')
  BEGIN
   UPDATE P SET ACTIVO=CASE WHEN @OPERACION='HABILITAR' AND EXISTS(SELECT 1 FROM dbo.V_ACA_CICLOS_RESUMEN R WHERE R.CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND R.CORR_PERIODO_ACADEMICO=P.CORR_PERIODO_ACADEMICO AND R.SELECCIONADA=1) THEN 1 ELSE 0 END,
    USUARIO_ACTU=@SYS_LOGIN_USUARIO,ESTACION_ACTU=@SYS_ESTACION,FECHA_ACTU=GETDATE()
   FROM dbo.ACA_PERIODOS_ACADEMICOS P WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND ES_GESTIONADO_CICLO=1;
   INSERT dbo.ACA_PERIODOS_ACADEMICOS_BITACORA(CORR_PERIODO_ACADEMICO,CORR_SEDE,CORR_AREA_ACADEMICA,CORR_FACULTAD,CORR_CARRERA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,ACTIVO,USUARIO_CREA,ESTACION_CREA,FECHA_CREA,USUARIO_ACTU,ESTACION_ACTU,FECHA_ACTU,TIPO_CAMBIO,USUARIO_CAMBIO)
   SELECT CORR_PERIODO_ACADEMICO,CORR_SEDE,CORR_AREA_ACADEMICA,CORR_FACULTAD,CORR_CARRERA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,ACTIVO,USUARIO_CREA,ESTACION_CREA,FECHA_CREA,USUARIO_ACTU,ESTACION_ACTU,FECHA_ACTU,'CICLO',@SYS_LOGIN_USUARIO FROM dbo.ACA_PERIODOS_ACADEMICOS WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO AND ES_GESTIONADO_CICLO=1;
  END;
  UPDATE dbo.ACA_CICLOS_ACADEMICOS SET USUARIO_ACTU=@SYS_LOGIN_USUARIO,ESTACION_ACTU=@SYS_ESTACION,FECHA_ACTU=GETDATE() WHERE CORR_CICLO_ACADEMICO=@CORR_CICLO_ACADEMICO;
  EXEC dbo.PR_ACA_CICLO_AUDITAR @CORR_CICLO_ACADEMICO,@OPERACION,@SYS_LOGIN_USUARIO,@SYS_ESTACION;
  IF @T=0 COMMIT TRANSACTION;
 END TRY BEGIN CATCH
  IF @T=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;ELSE IF @T>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION CICLOS_MTTO;
  SELECT @SYS_NUMERO_ERROR=ERROR_NUMBER(),@SYS_MENSAJE_ERROR=ERROR_MESSAGE();
  IF @SYS_NUMERO_ERROR IN(2601,2627) SELECT @SYS_NUMERO_ERROR=51000,@SYS_MENSAJE_ERROR=N'Ya existe ese ciclo en el área, o la asignación está duplicada.';
 END CATCH;
END;
GO
-- Agrupa el legado, sin cambiar sus PK, fechas, auditoría ni ACTIVO. No presupone carreras por alcance general.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
INSERT dbo.ACA_CICLOS_ACADEMICOS(CORR_EMPRESA,CORR_AREA_ACADEMICA,ANIO,NUMERO_PERIODO,FECHA_INICIO,FECHA_FIN,FECHA_INICIO_INSCRIPCION,FECHA_FIN_INSCRIPCION,REQUIERE_REVISION,USUARIO_CREA,ESTACION_CREA)
SELECT G.CORR_EMPRESA,G.CORR_AREA_ACADEMICA,G.ANIO,G.NUMERO_PERIODO,P.FECHA_INICIO,P.FECHA_FIN,P.FECHA_INICIO_INSCRIPCION,P.FECHA_FIN_INSCRIPCION,1,'juanh','IMPORTACION-CICLOS'
FROM(SELECT DISTINCT S.CORR_EMPRESA,P.CORR_AREA_ACADEMICA,P.ANIO,P.NUMERO_PERIODO FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.GEN_SEDES S ON S.CORR_SEDE=P.CORR_SEDE WHERE P.NUMERO_PERIODO IS NOT NULL) G
CROSS APPLY(SELECT TOP(1) P.* FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.GEN_SEDES S ON S.CORR_SEDE=P.CORR_SEDE WHERE S.CORR_EMPRESA=G.CORR_EMPRESA AND P.CORR_AREA_ACADEMICA=G.CORR_AREA_ACADEMICA AND P.ANIO=G.ANIO AND P.NUMERO_PERIODO=G.NUMERO_PERIODO ORDER BY CASE WHEN P.CORR_FACULTAD IS NULL AND P.CORR_CARRERA IS NULL THEN 0 ELSE 1 END,P.CORR_PERIODO_ACADEMICO) P
WHERE NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_ACADEMICOS C WHERE C.CORR_EMPRESA=G.CORR_EMPRESA AND C.CORR_AREA_ACADEMICA=G.CORR_AREA_ACADEMICA AND C.ANIO=G.ANIO AND C.NUMERO_PERIODO=G.NUMERO_PERIODO);
UPDATE P SET CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.GEN_SEDES S ON S.CORR_SEDE=P.CORR_SEDE
JOIN dbo.ACA_CICLOS_ACADEMICOS C ON C.CORR_EMPRESA=S.CORR_EMPRESA AND C.CORR_AREA_ACADEMICA=P.CORR_AREA_ACADEMICA AND C.ANIO=P.ANIO AND C.NUMERO_PERIODO=P.NUMERO_PERIODO WHERE P.CORR_CICLO_ACADEMICO IS NULL;
INSERT dbo.ACA_CICLOS_SEDES SELECT P.CORR_CICLO_ACADEMICO,P.CORR_SEDE,CAST(MAX(CAST(P.ACTIVO AS int)) AS bit) FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.ACA_CICLOS_ACADEMICOS C ON C.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND C.REQUIERE_REVISION=1
WHERE NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_SEDES S WHERE S.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND S.CORR_SEDE=P.CORR_SEDE) GROUP BY P.CORR_CICLO_ACADEMICO,P.CORR_SEDE;
INSERT dbo.ACA_CICLOS_FACULTADES_SEDES SELECT P.CORR_CICLO_ACADEMICO,P.CORR_SEDE,P.CORR_FACULTAD,CAST(MAX(CAST(P.ACTIVO AS int)) AS bit) FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.ACA_CICLOS_ACADEMICOS C ON C.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND C.REQUIERE_REVISION=1
WHERE P.CORR_FACULTAD IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_FACULTADES_SEDES F WHERE F.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND F.CORR_SEDE=P.CORR_SEDE AND F.CORR_FACULTAD=P.CORR_FACULTAD) GROUP BY P.CORR_CICLO_ACADEMICO,P.CORR_SEDE,P.CORR_FACULTAD;
INSERT dbo.ACA_CICLOS_CARRERAS_SEDES SELECT P.CORR_CICLO_ACADEMICO,P.CORR_SEDE,P.CORR_FACULTAD,P.CORR_CARRERA,P.ACTIVO,P.CORR_PERIODO_ACADEMICO FROM dbo.ACA_PERIODOS_ACADEMICOS P JOIN dbo.ACA_CICLOS_ACADEMICOS C ON C.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND C.REQUIERE_REVISION=1
WHERE P.CORR_CARRERA IS NOT NULL AND P.CORR_FACULTAD IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_CARRERAS_SEDES R WHERE R.CORR_CICLO_ACADEMICO=P.CORR_CICLO_ACADEMICO AND R.CORR_SEDE=P.CORR_SEDE AND R.CORR_CARRERA=P.CORR_CARRERA);
DECLARE @id int;DECLARE C_IMPORT CURSOR LOCAL FAST_FORWARD FOR SELECT CORR_CICLO_ACADEMICO FROM dbo.ACA_CICLOS_ACADEMICOS C WHERE REQUIERE_REVISION=1 AND NOT EXISTS(SELECT 1 FROM dbo.ACA_CICLOS_BITACORA B WHERE B.CORR_CICLO_ACADEMICO=C.CORR_CICLO_ACADEMICO);
OPEN C_IMPORT;FETCH NEXT FROM C_IMPORT INTO @id;WHILE @@FETCH_STATUS=0 BEGIN EXEC dbo.PR_ACA_CICLO_AUDITAR @id,'IMPORTACION','juanh','IMPORTACION-CICLOS';FETCH NEXT FROM C_IMPORT INTO @id;END;CLOSE C_IMPORT;DEALLOCATE C_IMPORT;
COMMIT TRANSACTION;
GO
UPDATE dbo.SEG_OPCION_SISTEMA SET NOMBRE_OPCION=N'Ciclos académicos por área',USUARIO_ACTU='juanh',ESTACION_ACTU='IMPLEMENTACION-CICLOS',FECHA_ACTU=GETDATE()
WHERE CODIGO_OPCION='ACA_PERIODOS_ACADEMICOS';
GO
